test('invoiceTotals with complex discount and VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 12.5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 10625);
  assert.equal(totals.vat, 15619);
});

test('invoiceTotals returns integer values', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert(Number.isInteger(totals.subtotal));
  assert(Number.isInteger(totals.discount));
  assert(Number.isInteger(totals.vat));
  assert(Number.isInteger(totals.voucher));
  assert(Number.isInteger(totals.total));
});

test('invoiceTotals with large values', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'BRAND-BOOK', name: 'Brand book', qty: 10, unitPrice: 245000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 2450000);
  assert(totals.vat > 0);
  assert.equal(totals.total, 2450000 + totals.vat);
});

test('invoiceTotals with bulk discount at exactly 10 units', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line: 85000, no line discount, bulk 2.5% = 2125, after 82875, VAT roundCents(82875 * 0.21) = 17404
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 17404);
});

test('invoiceTotals without bulk discount at 9 units', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 9, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line: 76500, no line discount, no bulk, VAT 16065
  assert.equal(totals.subtotal, 76500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 16065);
});

test('invoiceTotals bulk discount applied after line discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line: 85000, line discount 10% = 8500, after 76500
  // Bulk discount 2.5% of 76500 = 1912
  // Total discount: 8500 + 1912 = 10412
  // After all discounts: 74588, VAT 15663
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 10412);
  assert.equal(totals.vat, 15663);
});

test('invoiceTotals with multiple lines and bulk discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'ICON-SET', name: 'Icon set', qty: 5, unitPrice: 980, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 85000, bulk 2125, after 82875, VAT 17403
  // Line 2: 4900, no bulk, VAT 1029
  // Total: 85000 + 4900 = 89900, discount 2125, VAT 18432
  assert.equal(totals.subtotal, 89900);
  assert.equal(totals.discount, 2125);
});

test('invoiceTotals bulk discount with 100+ units', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'ICON-SET', name: 'Icon set', qty: 100, unitPrice: 980, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line: 98000, bulk 2.5% = 2450, after 95550, VAT 20066
  assert.equal(totals.subtotal, 98000);
  assert.equal(totals.discount, 2450);
});

test('invoiceTotals bulk discount does not apply to single unit', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line: 120000, no bulk discount
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 0);
});

test('invoiceTotals bulk discount with line discount combined', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 20, unitPrice: 8500, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line: 170000, line discount 5% = 8500, after 161500
  // Bulk 2.5% = roundCents(161500 * 0.025) = 4038, total discount 12538
  assert.equal(totals.subtotal, 170000);
  assert.equal(totals.discount, 12538);
});

test('invoiceTotals bulk discount VAT is on reduced amount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
