test('invoiceTotals with different VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 0 },
    ],
  };
  // Line 1: 85000 * 21 / 100 = 17850
  // Line 2: 3700 * 9 / 100 = 333
  const subtotal = 85000 + 3700;
  const vat = 17850 + 333;
  assert.deepEqual(invoiceTotals(invoice), { subtotal, discount: 0, vat, voucher: 0, total: subtotal + vat });
});

test('invoiceTotals with empty lines returns 0', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [],
  };
  assert.deepEqual(invoiceTotals(invoice), { subtotal: 0, discount: 0, vat: 0, voucher: 0, total: 0 });
});

test('invoiceTotals does not mutate the invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));
  invoiceTotals(invoice);
  assert.deepEqual(invoice, invoiceCopy);
});

test('addLine adds a new line to the invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const r = addLine(invoice, { sku: 'ICON-SET', qty: 2 });
