  assert.equal(r.value.dueDate, '2026-10-31');
});

test('createInvoice with EOM terms handles February', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-01',
    terms: 'EOM',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2026-02-28');
});

test('createInvoice with EOM terms handles leap year February', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-01',
