    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal: 42500, discount: 4250, afterDiscount: 38250, VAT: 38250 * 21 / 100 = 8032.5 -> 8032 (banker's rounding)
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 4250);
  assert.equal(totals.vat, 8032);
  assert.equal(totals.total, 42500 - 4250 + 8032);
});

